INSTITUTION = re.compile(r'egyetem|akadémia|университет|гимназия|πανεπιστ|ελκε|ειδικος λογαριασμος|sveučilišt|fakultet|yliopisto|\bumc\b|\broc\b|\bmbo\b|tu/e|kutató|szakképzési|business school|skillnet|sykehus|fimlab|\bvtt\b|zrt|részvénytársaság|eskom|rand water|\bwater\b|la poste|an post|irish rail|iarnród|bus eireann|ns groep|ruter|veikkaus|norsk tipping|yleisradio|\bhrt\b|hep d\.d|\bbank\b|\bbanka\b|national bank|nemzeti bank|norges bank|\boy\b|\bas\b|\bhf\b|\bgie\b|g\.e\.i\.e|\bgip\b|opco|stichting|univers|universidad|universidade|universit|hochschule|politechni|politecn|akadem|academ|college|institut|fundaç|fundaci|stiftung|hospital|szpital|klinik|spital|nemocnic|sairaala|ziekenhuis|clinic|opieki zdrowotnej|centrum (onkolog|zdrowia|medyczn)|research|forschung|fraunhofer|max-planck|helmholtz|\bdlr\b|gesellschaft|gmbh|\bltd\b|limited|\bplc\b|s\.a\.|\bsa\b|s\.p\.a|\bspa\b|\bag\b|e\.\s?v\.|sp\. z o\.o|товариств|акціонерн|компанія|підприємств|empresa|kammer|chamber|asociat|association|foundation|\bfond|фонд|благодійн|ebserh|fiocruz|oswaldo cruz|consorci|agrupaci', re.I)

BRANCH = {'Health': 'Health', 'Defence and armed forces': 'Defence', 'Police and public security': 'Police, justice and home affairs', 'Justice, courts and prosecutors': 'Police, justice and home affairs',
      'Interior, migration and home affairs': 'Police, justice and home affairs', 'Tax, customs and finance': 'Tax, finance and customs', 'Social security, labour and pensions': 'Social security and employment',
      'Digital government and public IT': 'Digital government and public IT', 'Economy, industry and innovation': 'Economy, industry and innovation',
      'Science and research ministries and funders': 'Research and science', 'Universities and research institutes': 'Education and universities',
      'Education ministries and schools': 'Education and universities', 'Environment, energy and utilities': 'Environment, energy and utilities', 'Transport and infrastructure': 'Transport',
      'Agriculture and food': 'Agriculture and food', 'Culture, media and sport': 'Culture, media and sport', 'Housing': 'Housing and community',
      'Head of government, parliament and cabinet': 'Central government (general)', 'Regulators and supervisors': 'Economy, industry and innovation',
      'State-owned companies': 'Economy, industry and innovation', 'EU institutions and agencies': 'EU institutions', 'Local and regional government': 'Local and regional government (general)',
      'Other national ministries and agencies': 'Central government (general)'}
GENERIC = {'Central government (general)', 'Local and regional government (general)', None}


def level(buyer):
    if LOCAL.search(buyer or ''): return 'Local'
    if REGIONAL.search(buyer or ''): return 'Regional'
    if NATIONAL.search(buyer or ''): return 'National'
    if INSTITUTION.search(buyer or ''): return 'Public institutions and companies'
    return 'Not stated'

def branch(buyer, lvl=None):
    b = BRANCH.get(first(BUYER, buyer or ''))
    if b and b not in GENERIC: return b
    if b: return b
    lvl = lvl or level(buyer)
    return 'Local and regional government (general)' if lvl in ('Local', 'Regional') else 'Central government (general)' if lvl == 'National' else 'Other / not stated'
